// Oeste BlockFooter — Topanga block (v0.4.8).
// A full page section composed from Oeste components, inlined below so
// this file is self-contained. Copy-paste ready. Requires: React 18+,
// Tailwind with dark: variant, JSX transform.
// Requires Topanga tokens: import src/tokens.css once (or copy src/tokens.json).
// Source: https://github.com/eric2busy/Oeste/blob/main/topanga/src/blocks.js
// Docs: https://oeste.hiddeninwest.com/topanga/#/blocks/footer
import React from "react";

const FOCUS = "focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-[#1c1917] dark:focus-visible:outline-[#f5f3ef]";

const TOUCH = "min-h-11";

const BUTTON_VARIANTS = {
  primary: "bg-[#c47d3b] text-[#1c1917] hover:opacity-90 dark:bg-[#db914e] dark:text-[#1c1917]",
  secondary: "border border-[#1c1917]/20 bg-transparent text-[#1c1917] hover:bg-[#1c1917]/5 dark:border-[#f5f3ef]/20 dark:text-[#f5f3ef] dark:hover:bg-[#f5f3ef]/5",
  ghost: "bg-transparent text-[#1c1917] hover:bg-[#1c1917]/5 dark:text-[#f5f3ef] dark:hover:bg-[#f5f3ef]/5",
  danger: "bg-[#a83e22] text-[#f6f4f1] hover:opacity-90 dark:bg-[#e07a52] dark:text-[#121110]",
};

const BUTTON_SIZES = {
  sm: "px-3 py-2 text-sm",
  md: "px-5 py-3 text-base",
  lg: "px-6 py-3.5 text-lg",
};

const FIELD = "min-h-11 w-full rounded-md border border-[#1c1917]/20 bg-transparent px-3 py-3 text-[#1c1917] placeholder:text-[#706963] dark:border-[#f5f3ef]/20 dark:text-[#f5f3ef] dark:placeholder:text-[#9e968f]";

export function Button({ children, variant = "primary", size = "md", disabled = false, loading = false, type = "button", onClick, icon = null }) {
  return (
    <button
      type={type}
      disabled={disabled || loading}
      onClick={onClick}
      aria-busy={loading || undefined}
      className={`${TOUCH} inline-flex items-center justify-center gap-2 rounded-md font-semibold disabled:cursor-not-allowed disabled:opacity-50 ${BUTTON_VARIANTS[variant]} ${BUTTON_SIZES[size]} ${FOCUS}`}
    >
      {loading ? <span aria-hidden="true">…</span> : icon}
      {children}
    </button>
  );
}

export function Input({ label, value, onChange, error, disabled = false, hint, id: idProp, ...rest }) {
  const autoId = React.useId();
  const id = idProp || autoId;
  const errorId = error ? `${id}-error` : undefined;
  const hintId = hint ? `${id}-hint` : undefined;
  return (
    <div>
      <label htmlFor={id} className="mb-2 block text-sm font-medium text-[#1c1917] dark:text-[#f5f3ef]">{label}</label>
      <input
        id={id} value={value} onChange={onChange} disabled={disabled}
        aria-invalid={!!error} aria-describedby={[errorId, hintId].filter(Boolean).join(" ") || undefined}
        className={`${FIELD} ${error ? "border-[#a83e22] dark:border-[#e07a52]" : ""} disabled:opacity-50 ${FOCUS}`} {...rest}
      />
      {hint && !error && <p id={hintId} className="mt-2 text-sm text-[#706963] dark:text-[#9e968f]">{hint}</p>}
      {error && <p id={errorId} role="status" className="mt-2 text-sm text-[#a83e22] dark:text-[#e07a52]">{error}</p>}
    </div>
  );
}

export function Separator({ orientation = "horizontal", decorative = true }) {
  if (orientation === "vertical") {
    return decorative
      ? <span aria-hidden="true" className="inline-block w-px self-stretch bg-[#1c1917]/10 dark:bg-[#f5f3ef]/10" />
      : <span role="separator" aria-orientation="vertical" className="inline-block w-px self-stretch bg-[#1c1917]/10 dark:bg-[#f5f3ef]/10" />;
  }
  return decorative
    ? <hr aria-hidden="true" className="my-4 border-0 border-t border-[#1c1917]/10 dark:border-[#f5f3ef]/10" />
    : <hr role="separator" aria-orientation="horizontal" className="my-4 border-0 border-t border-[#1c1917]/10 dark:border-[#f5f3ef]/10" />;
}

export function BlockFooter({ variant = "standard" }) {
  const columns = [
    { heading: "Product", links: ["Features", "Pricing", "Journal", "Changelog"] },
    { heading: "Studio", links: ["About", "Customers", "Careers", "Contact"] },
    { heading: "Resources", links: ["Help centre", "Guides", "Community", "Status"] },
  ];
  return (
    <footer className="bg-[#f6f4f1] px-6 pb-10 text-[#1c1917] dark:bg-[#121110] dark:text-[#f5f3ef] lg:px-8">
      <div className="mx-auto max-w-[1200px]">
        <Separator />
        <div className="grid gap-10 py-12 lg:grid-cols-[1fr_2fr]">
          <div>
            <p className="text-lg font-bold tracking-[-0.025em]">Fieldbook</p>
            <p className="mt-3 max-w-[320px] leading-relaxed text-[#706963] dark:text-[#9e968f]">A project journal for small studios: notes, decisions, and files on one calm page.</p>
            {variant === "newsletter" ? (
              <form className="mt-6 max-w-[320px]" onSubmit={(e) => e.preventDefault()}>
                <Input id="footer-newsletter-email" label="Email address" value="" onChange={() => {}} type="email" autoComplete="email" hint="One email a month, on running a calmer studio." />
                <div className="mt-3">
                  <Button variant="secondary" type="submit">Subscribe</Button>
                </div>
              </form>
            ) : null}
          </div>
          <nav aria-label="Footer" className="grid grid-cols-2 gap-8 sm:grid-cols-3">
            {columns.map((col) => (
              <div key={col.heading}>
                <h3 className="text-sm font-semibold">{col.heading}</h3>
                <ul className="mt-4 list-none space-y-1 p-0">
                  {col.links.map((l) => (
                    <li key={l}>
                      <a href="#" className="inline-flex min-h-11 items-center text-[#706963] hover:text-[#1c1917] dark:text-[#9e968f] dark:hover:text-[#f5f3ef]">{l}</a>
                    </li>
                  ))}
                </ul>
              </div>
            ))}
          </nav>
        </div>
        <Separator />
        <div className="flex flex-col gap-3 pt-6 text-sm text-[#706963] dark:text-[#9e968f] lg:flex-row lg:items-center">
          <p>Copyright 2026 Fieldbook Studio. All rights reserved.</p>
          <p className="flex gap-6 lg:ml-auto">
            <a href="#" className="inline-flex min-h-11 items-center hover:text-[#1c1917] dark:hover:text-[#f5f3ef]">Privacy</a>
            <a href="#" className="inline-flex min-h-11 items-center hover:text-[#1c1917] dark:hover:text-[#f5f3ef]">Terms</a>
            <a href="#" className="inline-flex min-h-11 items-center hover:text-[#1c1917] dark:hover:text-[#f5f3ef]">Licence</a>
          </p>
        </div>
      </div>
    </footer>
  );
}
